  ('cand_org_baobab_plus_dfb4f865', 'sweep-2026-08-epc-minigrid-002', 'agent_web_sweep', 'Baobab Plus', '', 'NG', 'org_role_distributor', 'org_segment_shs_paygo', 'org_group_oems', 'Named in REA''s first Nigeria DARES grant signing as one of eight standalone-solar awardees (tier 1 and 2 plug-and-play solar home systems).', 'https://nep.rea.gov.ng/posts/Press_Release_First_DARES_Signing.html', 1),
  ('cand_org_advad_limited_5fa849cb', 'sweep-2026-08-epc-minigrid-002', 'agent_web_sweep', 'ADVAD LIMITED', 'http://www.advadlimited.com', 'NG', 'org_role_epc,org_role_om_asset_manager,org_role_installer', 'org_segment_commercial_industrial,org_segment_utility_generation', 'org_group_epcs', 'Own site lists ''Engineering, Procurement & Construction'', ''Power Plant Operation & Maintenance'', renewable energy projects, rural electrification and power quality audits; ''14 Years Of Experience In Power & Electrical Infrastructure''. Listed in the REAN member directory (Agidingbi, Ikeja, Lagos).', 'http://www.advadlimited.com', 0),
  ('cand_org_income_electrix_limited_4ca27dc7', 'sweep-2026-08-epc-minigrid-002', 'agent_web_sweep', 'Income Electrix Limited', 'http://www.incomeelectrix.com', 'NG', 'org_role_epc,org_role_om_asset_manager,org_role_equipment_supplier', 'org_segment_transmission_distribution,org_segment_utility_generation,org_segment_commercial_industrial', 'org_group_epcs', 'Own site: ''Thermal and renewable plant EPC, gas turbines, diesel generators, solar PV, and small hydro systems'' and ''66kV-500kV transmission lines, 25KvA - 300MvA substations, 33kV-11kV distribution networks''; also utility O&M and meter/transformer manufacturing. Listed as ''Income Electrix Limited'' in the REAN member directory (Port Harcourt).', 'http://www.incomeelectrix.com', 0),
  ('cand_org_solarmate_engineering_limited_c2245101', 'sweep-2026-08-epc-minigrid-002', 'agent_web_sweep', 'Solarmate Engineering Limited', 'https://solarmateng.com/', 'NG', 'org_role_epc,org_role_installer,org_role_om_asset_manager,org_role_developer_ipp', 'org_segment_minigrids,org_segment_commercial_industrial', 'org_group_epcs', 'Own site: ''an engineering firm established in January 1996 as a renewable energy solutions provider''; services listed include design and engineering, procurement and installation, ''Solar Mini Grid'' and ''Operations and maintenance''; 400+ completed projects. Listed in the REAN member directory (Surulere, Lagos).', 'https://solarmateng.com/', 0),
  ('cand_org_solad_integrated_power_solutions_limited_39812643', 'sweep-2026-08-epc-minigrid-002', 'agent_web_sweep', 'SOLAD Integrated Power Solutions Limited', 'https://solad.co', 'NG', 'org_role_epc,org_role_om_asset_manager,org_role_developer_ipp', 'org_segment_minigrids,org_segment_commercial_industrial', 'org_group_epcs', 'Own site: ''Design and Implementation of tailored, fit for purpose solar and solar-hybrid energy solutions'' and ''Operation and maintenance services of energy assets''; describes itself as investor, developer and operator with 1.6 MW and 75 kW solar hybrid projects. Listed as ''Solad Integrated Power Solution'' in the REAN member directory.', 'https://solad.co', 0),
  ('cand_org_solusoft_nigeria_limited_061cb557', 'sweep-2026-08-epc-minigrid-002', 'agent_web_sweep', 'Solusoft Nigeria Limited', 'https://www.solusoft.com.ng', 'NG', 'org_role_epc,org_role_equipment_supplier,org_role_developer_ipp', 'org_segment_minigrids,org_segment_commercial_industrial', 'org_group_epcs', 'Own site: ''a wholly indigenous Engineering, Procurement and Construction (EPC) company and Original Equipment Manufacturer (OEM), established in 2010''; cites isolated mini-grids of 59 kW-363 kW in Kogi State and 30 kW C&I installations. Listed as ''SoluSoft Nigeria Limited'' in the REAN member directory (Abuja).', 'https://www.solusoft.com.ng', 0),
  ('cand_org_bartum_energy_024035e1', 'sweep-2026-08-epc-minigrid-002', 'agent_web_sweep', 'Bartum Energy', 'http://www.bartumenergy.com', 'NG', 'org_role_epc,org_role_installer,org_role_equipment_supplier', 'org_segment_commercial_industrial,org_segment_energy_storage,org_segment_utility_generation', 'org_group_epcs', 'Own site: ''ONE-STOP SOLUTIONS PROVIDER FOR SOLAR POWER'' offering turnkey systems, ''Engineered Mounting Solutions for Utility-Scale Solar Farms'' and containerised 5 MWh battery energy storage; 200+ installations since 2016. Listed as ''BARTUM ENERGY LIMITED'' in the REAN member directory (Wuye, Abuja).', 'http://www.bartumenergy.com', 0),
  ('cand_org_ascend_systems_limited_2d89c355', 'sweep-2026-08-epc-minigrid-002', 'agent_web_sweep', 'Ascend Systems Limited', 'http://www.ascendsystems.ng', 'NG', 'org_role_epc,org_role_installer,org_role_distributor', 'org_segment_commercial_industrial', 'org_group_epcs', 'Own site: ''We design, supply, and install precision solar systems for homes, factories, and estates''; residential 3-30 kVA and commercial/industrial solar; 150+ installations, 7+ years. Listed in the REAN member directory (Garki, Abuja).', 'http://www.ascendsystems.ng', 0);

insert or ignore into organisation_candidates (id, batch_id, source_kind, name, website, countries, role_ids, segment_ids, actor_group_id, evidence_note, source_url, flagged_personal) values
  ('cand_org_dvs_reliable_energy_limited_37c2cfcd', 'sweep-2026-08-epc-minigrid-003', 'agent_web_sweep', 'DVS Reliable Energy Limited', 'https://dvsreliableenergy.com/', 'NG', 'org_role_epc,org_role_installer,org_role_om_asset_manager', 'org_segment_commercial_industrial', 'org_group_epcs', 'Own site: residential, ''Commercial and Industrial Solar'' and off-grid systems, plus ''Expert upkeep and repair services''; ''end-to-end solar solutions''; 700+ installations, offices in Lagos, Ibadan and Osogbo. Listed as ''DVS Reliable Energy'' in the REAN member directory (Surulere, Lagos).', 'https://dvsreliableenergy.com/', 0),
  ('cand_org_e_phaim_energy_limited_bfc6ce92', 'sweep-2026-08-epc-minigrid-003', 'agent_web_sweep', 'e-Phaim Energy Limited', 'https://ephaimenergy.com.ng', 'NG', 'org_role_system_integrator,org_role_installer,org_role_om_asset_manager', 'org_segment_commercial_industrial', 'org_group_epcs', 'Own site: ''As a System Integrator, we are involved with our Clients from the first stage of Project Development up to the installation and maintenance''; ''Over 2.5MWp Solar Hybrid System deployed nationwide''. Listed in the REAN member directory (Gaduwa Estate, Abuja).', 'https://ephaimenergy.com.ng', 0),
  ('cand_org_saf_aga_renewable_energy_ltd_4e23d2bf', 'sweep-2026-08-epc-minigrid-003', 'agent_web_sweep', 'Saf-Aga Renewable Energy Ltd.', 'https://safagaenergy.com/', 'NG', 'org_role_installer,org_role_developer_ipp,org_role_energy_service_company', 'org_segment_minigrids,org_segment_productive_use,org_segment_commercial_industrial', 'org_group_epcs', 'Own site lists ''Solar Mini-Grid'' setup and installation, productive-use equipment (solar pumps, grinding machines, electric tricycles), C&I lithium/inverter systems, solar street lights and ''Energy As a Service''. Listed as ''Saf-Aga Renewable Energy Ltd.'' in the REAN member directory (Wuse Zone 5, Abuja).', 'https://safagaenergy.com/', 0),
  ('cand_org_sao_energy_services_africa_ltd_a0213f8c', 'sweep-2026-08-epc-minigrid-003', 'agent_web_sweep', 'SAO ENERGY SERVICES AFRICA LTD', 'http://www.saoenergy.com', 'NG', 'org_role_developer_ipp,org_role_epc,org_role_energy_service_company', 'org_segment_commercial_industrial,org_segment_minigrids', 'org_group_developers', 'Listed in the REAN member directory (Maitama, Abuja) with website saoenergy.com. That site describes solar, hydro, gas and biomass ''energy solutions'', ''Energy-As-A-Service'', and project delivery for healthcare facility electrification and communities in sub-Saharan Africa.', 'https://rean.org.ng/our-members/page/2/', 0),
  ('cand_org_greenvale_energy_ltd_797cee81', 'sweep-2026-08-epc-minigrid-003', 'agent_web_sweep', 'Greenvale Energy Ltd', 'http://www.greenvaleenergy.com.ng', 'NG', 'org_role_system_integrator,org_role_epc,org_role_installer', 'org_segment_commercial_industrial', 'org_group_epcs', 'Own site: ''a reputable indigenous Nigerian energy services company and systems integrator, providing comprehensive, end-to-end solutions''; residential and commercial solar installation, maintenance and monitoring, plus engineering and construction. Listed as ''GREENVALE ENERGY LTD'' in the REAN member directory (CBD, Abuja).', 'http://www.greenvaleenergy.com.ng', 0),
  ('cand_org_goshbeth_limited_f80a0902', 'sweep-2026-08-epc-minigrid-003', 'agent_web_sweep', 'Goshbeth Limited', 'http://www.goshbethlimited.com', 'NG', 'org_role_epc,org_role_installer,org_role_om_asset_manager', 'org_segment_commercial_industrial', 'org_group_epcs', 'Own site: ''Goshbeth Limited is a renewable energy firm based in Abuja focused on delivering solar power systems for homes, businesses, and institutions''; solar design and installation, maintenance and repairs, energy audits; portfolio includes a 325 kW system for an educational institution. Listed as ''GOSHBETH LIMITED'' in the REAN member directory (Lokogoma, Abuja).', 'http://www.goshbethlimited.com', 0),
  ('cand_org_primetech_energy_ltd_c35a062c', 'sweep-2026-08-epc-minigrid-003', 'agent_web_sweep', 'Primetech Energy Ltd.', 'http://www.primetechenergy.com.ng', 'NG', 'org_role_epc,org_role_installer,org_role_om_asset_manager', 'org_segment_minigrids,org_segment_commercial_industrial', 'org_group_epcs', 'Own site lists site assessment, system installation, mini-grid hybrid solar systems and quarterly inverter/battery maintenance; offices in Kano, Abuja and Kaduna with projects at Ahmadu Bello University. Listed as ''PrimeTech Energy limited'' in the REAN member directory (Tarauni, Kano).', 'http://www.primetechenergy.com.ng', 0),
  ('cand_org_vawell_power_solutions_limited_32d32bec', 'sweep-2026-08-epc-minigrid-003', 'agent_web_sweep', 'Vawell Power Solutions Limited', 'http://www.vawellpower.com', 'NG', 'org_role_epc,org_role_installer,org_role_om_asset_manager', 'org_segment_commercial_industrial,org_segment_transmission_distribution,org_segment_emobility', 'org_group_epcs', 'Listed as ''Vawell Power Solutions Limited'' in the REAN member directory (Abule-Egba, Lagos). Its site states: ''Solar power systems (homes, businesses, institutions); Large-scale electrical installations (factories, estates, schools, hospitals)'', plus transformer supply/repair, EV charging infrastructure, smart metering and turnkey projects; 300+ projects since 2019.', 'https://rean.org.ng/our-members/page/3/', 0),
  ('cand_org_ultra_rays_limited_caccaa06', 'sweep-2026-08-epc-minigrid-003', 'agent_web_sweep', 'Ultra Rays Limited', 'http://www.ultrarays.org', 'NG', 'org_role_epc,org_role_installer,org_role_om_asset_manager', 'org_segment_commercial_industrial', 'org_group_epcs', 'Listed as ''Ultra Rays Limited'' in the REAN member directory (Ikate Elegushi, Lagos). Its site (as ''Ultra Rays Ltd'') lists grid-tied, hybrid and off-grid solar installation and maintenance, electrical engineering services, energy audits and industrial/commercial power.', 'https://rean.org.ng/our-members/page/3/', 0),
  ('cand_org_treffen_renewable_energy_investment_ltd_a1a892f2', 'sweep-2026-08-epc-minigrid-003', 'agent_web_sweep', 'Treffen Renewable Energy Investment Ltd', 'https://treffen.ng', 'NG', 'org_role_epc,org_role_installer,org_role_om_asset_manager,org_role_distributor', 'org_segment_commercial_industrial,org_segment_shs_paygo', 'org_group_epcs', 'Listed as ''Treffen Renewable Energy Investment Ltd'' in the REAN member directory. Its site (Treffen Renewable Energy Investment Limited, TREIL) states ''Solar Home systems energy audits, solar power design, Installation and maintenance'', turn-key delivery, and close to 1 MW installed.', 'https://rean.org.ng/our-members/page/3/', 0),
  ('cand_org_fourier_energy_limited_038f0af4', 'sweep-2026-08-epc-minigrid-003', 'agent_web_sweep', 'FOURIER ENERGY LIMITED', 'http://www.fouriersolar.com', 'NG', 'org_role_installer,org_role_distributor,org_role_om_asset_manager', 'org_segment_commercial_industrial', 'org_group_epcs', 'Listed as ''FOURIER ENERGY LIMITED'' in the REAN member directory (Dei Dei, Abuja). Its site (Fourier Solar Energy) states ''Sales, Installation and Services of Solar Panels and Accessories'', with professional installation and post-installation maintenance and monitoring.', 'https://rean.org.ng/our-members/', 0),
  ('cand_org_brightaic_green_technologies_limited_ef4380f3', 'sweep-2026-08-epc-minigrid-003', 'agent_web_sweep', 'Brightaic Green Technologies Limited', 'http://www.brightaicgt.com', 'NG', 'org_role_installer,org_role_distributor', 'org_segment_commercial_industrial,org_segment_emobility', 'org_group_epcs', 'Listed as ''Brightaic Green Technologies Limited'' in the REAN member directory (Lekki, Lagos). Its site lists solar installation systems for homes and businesses, wholesale solar panel distribution (300-615 W) and EV charging infrastructure.', 'https://rean.org.ng/our-members/', 0),
  ('cand_org_energy_vision_nigeria_limited_c5c6e0a3', 'sweep-2026-08-epc-minigrid-003', 'agent_web_sweep', 'ENERGY VISION NIGERIA LIMITED', 'https://genergy.vision/', 'NG', 'org_role_energy_service_company,org_role_om_asset_manager', 'org_segment_commercial_industrial,org_segment_energy_storage', 'org_group_operators', 'Listed as ''ENERGY VISION NIGERIA LIMITED'' in the REAN member directory (Victoria Island, Lagos). Its site describes an ESCO offering ''Energy as a Service (EaaS) business models'' for telecom infrastructure - hybrid generation and storage, remote monitoring, preventive maintenance - managing ''over 11,000 sites''.', 'https://rean.org.ng/our-members/', 0),
  ('cand_org_zagus_power_systems_limited_f044297d', 'sweep-2026-08-epc-minigrid-003', 'agent_web_sweep', 'Zagus Power Systems Limited', 'http://www.zaguspower.com', 'NG', 'org_role_distributor,org_role_installer,org_role_om_asset_manager', 'org_segment_commercial_industrial,org_segment_energy_storage', 'org_group_oems', 'Own site: ''supplied, installed, and maintained critical power solutions'' - UPS systems, voltage stabilisers, energy storage and electrical infrastructure; exclusive distributor of Zektron products in Nigeria. Listed in the REAN member directory (Ikeja, Lagos).', 'http://www.zaguspower.com', 0),
  ('cand_org_smartace_nigeria_limited_8cbb36df', 'sweep-2026-08-epc-minigrid-003', 'agent_web_sweep', 'SMARTACE NIGERIA LIMITED', 'https://smartace.org/', 'NG', 'org_role_installer,org_role_distributor,org_role_om_asset_manager', 'org_segment_commercial_industrial,org_segment_energy_storage', 'org_group_epcs', 'Listed as ''SMARTACE NIGERIA LIMITED'' in the REAN member directory (Surulere, Lagos). Its site states: ''We specialize in the sale, supply, and installation of world-class power infrastructure, including inverters, inverter batteries, solar panels, UPS systems, and stabilizers'', and lists Operation & Maintenance. Note the same company also sells automobiles.', 'https://rean.org.ng/our-members/page/2/', 0),
  ('cand_org_lpv_technologies_c267d52d', 'sweep-2026-08-epc-minigrid-003', 'agent_web_sweep', 'LPV Technologies', 'https://lpvtechnologies.com', 'NG', 'org_role_equipment_supplier', 'org_segment_commercial_industrial,org_segment_minigrids', 'org_group_oems', 'Own site: vertically integrated Lagos-based solar panel manufacturer with a 200 MW semi-automated line producing PERC/TOPCon modules, supplying mini-grid projects, dealers/installers and public-sector procurement. Listed as ''LPV Technologies'' in the REAN member directory (Ikoyi, Lagos). Included as an equipment supplier/manufacturer, not an installer.', 'https://lpvtechnologies.com', 0),
  ('cand_org_uwana_energy_nigeria_limited_3dee356e', 'sweep-2026-08-epc-minigrid-003', 'agent_web_sweep', 'UWANA Energy Nigeria Limited', 'https://uwanaconnect.com', 'NG', 'org_role_energy_service_company', 'org_segment_commercial_industrial,org_segment_shs_paygo', 'org_group_operators', 'Own site (RC 1653731): ''Nigeria''s most trusted solar marketplace. We connect homeowners and businesses with the right solar system, verified installers, and flexible financing'', with a ''Finance -> Install -> Support'' model. Listed as ''UWANA Energy Nigeria Limited'' in the REAN member directory (Ikoyi, Lagos). It brokers rather than performs installation.', 'https://uwanaconnect.com', 0),
  ('cand_org_cosol_energy_solutions_limited_585eaa17', 'sweep-2026-08-epc-minigrid-003', 'agent_web_sweep', 'COSOL ENERGY SOLUTIONS LIMITED', 'http://www.tergoenergy.com', 'NG', 'org_role_to_classify', '', 'org_group_epcs', 'Listed as a member company in the REAN (Renewable Energy Association of Nigeria) directory, Victoria Island, Lagos, with website tergoenergy.com. The directory does not state the member''s role, and the site was not opened - role needs manual classification.', 'https://rean.org.ng/our-members/', 0),
  ('cand_org_ascend_systems_limited_abuja_8e669927', 'sweep-2026-08-epc-minigrid-003', 'agent_web_sweep', 'Ascend Systems Limited (Abuja)', 'http://www.ascendsystems.ng', 'NG', 'org_role_epc,org_role_installer', 'org_segment_commercial_industrial', 'org_group_epcs', 'Duplicate-safe REAN directory record for Ascend Systems Limited, Suite FF002 Neighbourhood Centre, Area 3, Garki, Abuja - same company as the ascendsystems.ng entry above; merge on ingest.', 'https://rean.org.ng/our-members/', 0),
