  ('cand_org_sunfi_technology_solutions_limited_2c96ccc5', 'sweep-2026-08-epc-minigrid-003', 'agent_web_sweep', 'SunFi Technology Solutions Limited.', 'https://www.sunfi.co', 'NG', 'org_role_to_classify', '', 'org_group_epcs', 'Listed as a member company in the REAN directory (Oniru, Lekki, Lagos) with website sunfi.co. The site returned no readable content, so the role could not be verified.', 'https://rean.org.ng/our-members/page/3/', 0),
  ('cand_org_greenstreak_energies_limited_a1055fce', 'sweep-2026-08-epc-minigrid-003', 'agent_web_sweep', 'GreenStreak Energies Limited', '', 'NG', 'org_role_to_classify', '', 'org_group_epcs', 'Listed as a member company in the REAN directory (Banana Island, Lagos). The website REAN gives (greenstreakenergies.com) no longer resolves, so no website is recorded and the role could not be verified.', 'https://rean.org.ng/our-members/', 0),
