  ('cand_org_tricell_solar_solutions_limited_e6e987f8', 'sweep-2026-08-epc-minigrid-004', 'agent_web_sweep', 'TriCell Solar Solutions Limited', 'https://www.linkedin.com/company/tricell-solar-solutions', 'NG', 'org_role_to_classify', '', 'org_group_epcs', 'Listed as a member company in the REAN directory (Ilupeju Estate, Lagos). REAN gives only a LinkedIn page rather than an own domain; role not verified.', 'https://rean.org.ng/our-members/page/3/', 0),
  ('cand_org_rayonnance_energy_fze_bf572eed', 'sweep-2026-08-epc-minigrid-004', 'agent_web_sweep', 'RAYONNANCE ENERGY FZE', 'https://www.weransolar.com', 'NG', 'org_role_to_classify', '', 'org_group_epcs', 'Listed as a member company in the REAN directory, Lekki Free Trade Zone, Ibeju Lekki, Lagos, with website weransolar.com. Role not verified.', 'https://rean.org.ng/our-members/page/2/', 0),
