insert or ignore into organisation_candidates (id, batch_id, source_kind, name, website, countries, role_ids, segment_ids, actor_group_id, evidence_note, source_url, flagged_personal) values
  ('cand_org_safi_sana_ghana_limited_eb2a4b49', 'sweep-2026-08-epc-minigrid-025', 'agent_web_sweep', 'Safi Sana (Ghana) Limited', '', 'GH', 'org_role_developer_ipp,org_role_om_asset_manager', 'org_segment_utility_generation', 'org_group_developers', 'Row 65 of the Energy Commission generation licence register: 100kW waste-to-energy plant, licence EC/GWSL/12-14-063, status Operational Licence — one of the few operational renewable generators in the register.', 'https://energycom.gov.gh/regnew/index.php/Energy/loadRegister/Provisional%20Wholesale%20Supply%20and%20Generation%20License%20Holders/7', 0),
  ('cand_org_upwind_ayitepa_e6edad54', 'sweep-2026-08-epc-minigrid-025', 'agent_web_sweep', 'Upwind Ayitepa', '', 'GH', 'org_role_developer_ipp', 'org_segment_utility_generation', 'org_group_developers', 'Row 73 of the Energy Commission generation licence register: 20MW solar, licence EC/GWSL/02-14-037 at CONSTRUCTION PERMIT stage. The same licence appears at row 41 as ''Upwind Ayitepa Ltd'', 300MW wind, Provisional.', 'https://energycom.gov.gh/regnew/index.php/Energy/loadRegister/Provisional%20Wholesale%20Supply%20and%20Generation%20License%20Holders/8', 1),
  ('cand_org_tfi_power_company_limited_2a9b37f2', 'sweep-2026-08-epc-minigrid-025', 'agent_web_sweep', 'TFI Power Company Limited', '', 'GH', 'org_role_developer_ipp', 'org_segment_utility_generation', 'org_group_developers', 'Row 108 of the Energy Commission generation licence register: 60MW solar, licence EC/GWSL/08-13-017 at CONSTRUCTION PERMIT stage.', 'https://energycom.gov.gh/regnew/index.php/Energy/loadRegister/Provisional%20Wholesale%20Supply%20and%20Generation%20License%20Holders/11', 0),
  ('cand_org_solarplast_project_company_limited_66a63269', 'sweep-2026-08-epc-minigrid-025', 'agent_web_sweep', 'SolarPlast Project Company Limited', '', 'GH', 'org_role_developer_ipp,org_role_om_asset_manager', 'org_segment_commercial_industrial', 'org_group_developers', 'Rows 137 and 140 of the Energy Commission generation licence register: 704kWp grid-tied rooftop solar PV (EC/SOL/CP-14/05-20-010, Construction Permit) and 782kWp rooftop solar PV (EC/GWSL/11-20-006, Operational). Spelled ''Solarplast Project Company Limited'' at row 140.', 'https://energycom.gov.gh/regnew/index.php/Energy/loadRegister/Provisional%20Wholesale%20Supply%20and%20Generation%20License%20Holders/14', 0),
  ('cand_org_solar_for_industries_8beef159', 'sweep-2026-08-epc-minigrid-025', 'agent_web_sweep', 'Solar for Industries', '', 'GH', 'org_role_developer_ipp', 'org_segment_utility_generation,org_segment_commercial_industrial', 'org_group_developers', 'Named as the project lead for Ghana''s 200MW utility-scale solar park at Agortor in the Dawa Industrial Enclave (groundbreaking 6 November 2025), described as ''a unit of LMI Holdings'' and backed by the IFC. The article names no EPC contractor, referring only to ''international EPC contractors''.', 'https://africasustainabilitymatters.com/ghana-breaks-ground-on-200mw-solar-plant-targeting-1000mw-by-2032/', 0),
  ('cand_org_ensol_t_limited_052b86f8', 'sweep-2026-08-epc-minigrid-025', 'agent_web_sweep', 'Ensol (T) Limited', 'https://ensol.co.tz', 'TZ', 'org_role_epc,org_role_om_asset_manager,org_role_installer', 'org_segment_commercial_industrial,org_segment_productive_use', 'org_group_epcs', 'TAREA corporate member (listed as ENSOL TANZANIA LTD.). Own site: "ENSOL is a trusted EPC (Engineering, Procurement, and Construction) company serving East Africa", with grid-tied and hybrid PV, solar water pumping and a dedicated Operation & Maintenance service line.', 'https://ensol.co.tz/', 0),
  ('cand_org_resco_tanzania_ltd_90b54142', 'sweep-2026-08-epc-minigrid-025', 'agent_web_sweep', 'RESCO TANZANIA LTD', 'https://resco.co.tz', 'TZ', 'org_role_epc,org_role_installer,org_role_developer_ipp,org_role_om_asset_manager', 'org_segment_minigrids,org_segment_commercial_industrial,org_segment_productive_use', 'org_group_epcs', 'Listed as active TAREA corporate member. Own site (resco.co.tz): "Design, supply and Installation of renewable energy systems including Solar Electric Systems"; "We develop and operate solar mini-grid projects for electricity services in rural communities and institutions"; "Maintenance and repair of solar energy systems."', 'https://tarea-tz.org/our-work/corporate-members', 0),
  ('cand_org_sescom_ltd_7e4192d3', 'sweep-2026-08-epc-minigrid-025', 'agent_web_sweep', 'SESCOM LTD', 'https://www.sescom.co.tz', 'TZ', 'org_role_installer,org_role_epc,org_role_om_asset_manager', 'org_segment_minigrids,org_segment_productive_use,org_segment_clean_cooking', 'org_group_epcs', 'Listed as active TAREA corporate member. Own site: "Standalone, mini-grid and grid-connected solar systems" and "Licensed electrical contractor for MV/LV lines, transformers, panels and cable terminations to 33 kV"; site gives legal name TWENY LIMITED.', 'https://tarea-tz.org/our-work/corporate-members', 0),
  ('cand_org_power_provider_co_ltd_4083af3b', 'sweep-2026-08-epc-minigrid-025', 'agent_web_sweep', 'POWER PROVIDER CO. LTD.', 'https://powerproviders.co.tz', 'TZ', 'org_role_installer,org_role_om_asset_manager', 'org_segment_commercial_industrial,org_segment_productive_use', 'org_group_epcs', 'Listed as active TAREA corporate member. Own site (powerproviders.co.tz): solar power systems, solar water heating and solar water pumping for hotels, NGOs, schools and hospitals in Tanzania — "In addition to installation, power providers often offer maintenance, monitoring, and technical support"; site lists institutional, hospitality, commercial and residential reference installations.', 'https://tarea-tz.org/our-work/corporate-members', 0),
  ('cand_org_acon_electricals_limited_3f108f33', 'sweep-2026-08-epc-minigrid-025', 'agent_web_sweep', 'ACON ELECTRICALS LIMITED', 'http://www.acon.co.tz', 'TZ', 'org_role_epc,org_role_installer', 'org_segment_commercial_industrial,org_segment_transmission_distribution', 'org_group_epcs', 'Listed as active TAREA corporate member. Own site: "Acon Electricals Ltd is a general EPC (engineering, procurement, and construction) contractor committed to providing the highest quality electrical installations in Tanzania", with "solar power installations and power grid integration".', 'https://tarea-tz.org/our-work/corporate-members', 0),
  ('cand_org_compact_energies_ltd_2c67ccc6', 'sweep-2026-08-epc-minigrid-025', 'agent_web_sweep', 'COMPACT ENERGIES LTD.', 'https://compactenergies.co.tz', 'TZ', 'org_role_installer,org_role_distributor', 'org_segment_productive_use,org_segment_commercial_industrial', 'org_group_epcs', 'Listed as active TAREA corporate member. Own site: "We transform sunlight into savings through professional solar distribution and installation services", with a project list including solar power system, solar water heater and solar water pump installations.', 'https://tarea-tz.org/our-work/corporate-members', 0),
  ('cand_org_mevanti_tanzania_ltd_mevanti_energy_7752f8b3', 'sweep-2026-08-epc-minigrid-025', 'agent_web_sweep', 'MEVANTI TANZANIA LTD-MEVANTI ENERGY', 'http://www.mevantienergy.com', 'TZ', 'org_role_installer,org_role_om_asset_manager', 'org_segment_commercial_industrial,org_segment_energy_storage,org_segment_emobility', 'org_group_epcs', 'Listed as active TAREA corporate member. Own site: solar solutions "for residential, commercial, and industrial use" where "dedicated team provides full installation and ongoing support", plus energy storage (ESS) and EV charging.', 'https://tarea-tz.org/our-work/corporate-members', 0),
  ('cand_org_seanelec_tanzania_ltd_e95ad00d', 'sweep-2026-08-epc-minigrid-025', 'agent_web_sweep', 'SEANELEC TANZANIA LTD.', 'https://www.seanelec.co.tz', 'TZ', 'org_role_epc,org_role_installer,org_role_om_asset_manager', 'org_segment_commercial_industrial', 'org_group_epcs', 'Listed as active TAREA corporate member. Own site (Seanelec (T) Ltd, Arusha): "RENEWABLE ENERGY (SOLAR POWER)" service line and "Quality design. Reliable construction. Seamless operation & maintenance. Trusted project management."', 'https://tarea-tz.org/our-work/corporate-members', 0),
  ('cand_org_gaptech_electrical_electronics_ltd_c4643ced', 'sweep-2026-08-epc-minigrid-025', 'agent_web_sweep', 'GAPTECH ELECTRICAL & ELECTRONICS LTD.', 'http://www.gaptech.co.tz', 'TZ', 'org_role_installer,org_role_system_integrator', 'org_segment_commercial_industrial,org_segment_energy_storage', 'org_group_epcs', 'Listed as active TAREA corporate member. Own site (Dar es Salaam): provides "Solar power systems and Energy storage solutions" and states they "design and implement bespoke electrical and electronics systems", including electrical audits and distribution panel boards.', 'https://tarea-tz.org/our-work/corporate-members', 0),
  ('cand_org_jumeme_rural_power_supply_6b4a206e', 'sweep-2026-08-epc-minigrid-025', 'agent_web_sweep', 'JUMEME RURAL POWER SUPPLY', 'http://www.jumeme.com', 'TZ', 'org_role_developer_ipp,org_role_om_asset_manager', 'org_segment_minigrids', 'org_group_developers', 'Listed as active TAREA corporate member. Own site: "Jumeme is a mini-grid operator using solar-battery-diesel hybrid power systems connected to medium and low voltage distribution networks... to its customers in rural Tanzanian growth centres." Also named in the State of the Global Mini-Grids Market Report 2020 Tanzania case study as one of the two largest mini-grid operators in Tanzania.', 'https://tarea-tz.org/our-work/corporate-members', 0),
  ('cand_org_rift_valley_ltd_877bbe5d', 'sweep-2026-08-epc-minigrid-025', 'agent_web_sweep', 'RIFT VALLEY LTD', 'https://rve.co.tz', 'TZ', 'org_role_developer_ipp,org_role_om_asset_manager', 'org_segment_utility_generation,org_segment_minigrids,org_segment_transmission_distribution', 'org_group_developers', 'Listed as active TAREA corporate member (TAREA links to riftvalleyenergy.com, which redirects to rve.co.tz). Own site: "RVE Tanzania Ltd (RVE) is a Tanzania-based renewable-energy infrastructure project-development holding company that develops, owns, and operates relevant electricity generation and rural distribution project companies"; subsidiaries named include Mwenga Hydro Limited, Luponde Hydro Limited and Suma Hydro Limited.', 'https://tarea-tz.org/our-work/corporate-members', 0),
  ('cand_org_rafiki_power_7bd70dc1', 'sweep-2026-08-epc-minigrid-025', 'agent_web_sweep', 'Rafiki Power', '', 'TZ', 'org_role_developer_ipp,org_role_om_asset_manager', 'org_segment_minigrids', 'org_group_developers', 'Named in the State of the Global Mini-Grids Market Report 2020 Tanzania case study: former E.ON subsidiary "which has built eight mini-grids ranging from 5kW to 50kW for customers in Tanzania"; acquired by PowerGen in August 2019.', 'https://minigrids.org/wp-content/uploads/2020/06/Tanzania-_Case_Study.pdf', 0),
  ('cand_org_devergy_227fbc2a', 'sweep-2026-08-epc-minigrid-025', 'agent_web_sweep', 'Devergy', '', 'TZ', 'org_role_developer_ipp,org_role_om_asset_manager', 'org_segment_minigrids,org_segment_productive_use', 'org_group_developers', 'Named in the State of the Global Mini-Grids Market Report 2020 Tanzania case study: "Devergy, a Tanzanian social energy utility, was founded in 2010 and began operating its first mini-grid two years later. The company installed an adaptive DC mini-grid system to supply 60 to 400 households with electricity."', 'https://minigrids.org/wp-content/uploads/2020/06/Tanzania-_Case_Study.pdf', 0),
  ('cand_org_nexus_green_limited_ab805f1e', 'sweep-2026-08-epc-minigrid-025', 'agent_web_sweep', 'NEXUS GREEN LIMITED', 'https://nexusgreen.com', 'UG', 'org_role_epc,org_role_installer', 'org_segment_productive_use,org_segment_commercial_industrial,org_segment_energy_storage', 'org_group_epcs', 'Holds ERA company electrical installation permit ERA/EIP/CLXM/023/07867, Class XM ("Company work not exceeding 66kV distribution voltage"), location Ntinda. Also a USEA member (listed as Nexus Green Ltd). Own site: "designing, supplying, manufacturing and delivering affordable solar-powered solutions" including solar irrigation, solar street lighting and "full turnkey solutions"; describes itself as a British company with a Uganda branch.', 'https://www.era.go.ug/certified-installation-permit-holders/', 0),
  ('cand_org_grid_engineering_u_ltd_1b19a73e', 'sweep-2026-08-epc-minigrid-025', 'agent_web_sweep', 'GRID ENGINEERING (U) LTD', '', 'UG', 'org_role_installer,org_role_epc', 'org_segment_commercial_industrial', 'org_group_epcs', 'Holds ERA company electrical installation permit ERA/EIP/CLX/018/02631, Class X, at Bombo Road, Ben Kiwanuka Street, Plot 88. Independently listed as a Uganda Solar Energy Association member (Plot 88 Ben Kiwanuka Street, Master Plaza) — regulator installation permit plus solar-association membership.', 'https://www.era.go.ug/certified-installation-permit-holders/', 0),
  ('cand_org_psi_engineering_uganda_limited_2a924a32', 'sweep-2026-08-epc-minigrid-025', 'agent_web_sweep', 'PSI Engineering Uganda Limited', 'https://www.psiengineering.co.ug', 'UG', 'org_role_epc,org_role_installer', 'org_segment_transmission_distribution,org_segment_commercial_industrial', 'org_group_epcs', 'USEA member operating in Northern, West Nile, Eastern, Central, Western and South West regions. Also holds ERA company installation permit ERA/EIP/CLX/021/04615, Class X (listed as PSI ENGINEERING). Own site: "Comprehensive power infrastructure development including transmission lines, substations, and distribution networks" plus renewable energy projects, and they "design, construct, and maintain infrastructure".', 'https://www.useaug.org/our-members/page/5/', 0),
  ('cand_org_reliefline_uganda_ltd_94431f69', 'sweep-2026-08-epc-minigrid-025', 'agent_web_sweep', 'RELIEFLINE UGANDA LTD', '', 'UG', 'org_role_installer', 'org_segment_commercial_industrial', 'org_group_epcs', 'USEA member at Plot 7629, Kiwafu Road, Kansanga. Also holds ERA company electrical installation permit ERA/EIP/CLX/023/06996, Class X (listed as RELIEFLINE UGANDA LIMITED, Plot 7629, Block 244 Kiwafu Road, Kampala) — matching address confirms the same entity. Note: the group site reliefline.net presents a disaster-relief products business and does not describe the Uganda energy work, so role is based on the ERA permit plus USEA membership.', 'https://www.useaug.org/our-members/page/5/', 0),
  ('cand_org_sagewood_limited_93984ed2', 'sweep-2026-08-epc-minigrid-025', 'agent_web_sweep', 'Sagewood Limited', 'https://www.sagewood.com', 'UG', 'org_role_installer,org_role_epc', 'org_segment_transmission_distribution,org_segment_commercial_industrial', 'org_group_epcs', 'Holds ERA company electrical installation permit ERA/EIP/CLX/018/02645, Class X, Plot 30 Lugogo Bypass, Regency Plaza, Kampala. Also a USEA member (17 Vubyabirenge Road, Ntinda). Own site confirms "regional offices located in Ghana, Uganda, Rwanda and Zambia" and a "Power (Electrical Transmission & Distribution)" sector line.', 'https://www.era.go.ug/certified-installation-permit-holders/', 0),
  ('cand_org_solar_nation_smc_ltd_b1dd02d7', 'sweep-2026-08-epc-minigrid-025', 'agent_web_sweep', 'SOLAR NATION SMC LTD', '', 'UG', 'org_role_installer', 'org_segment_commercial_industrial', 'org_group_epcs', 'Holds ERA company electrical installation permit ERA/EIP/CLX/026/10430, Class X, location Ntinda. Also a USEA member (listed as Solar Nation smc Ltd / SOLAR NATION-SMC LIMITED, Plot 4, Queen Maxima Road, Ministers Village, Ntinda). Website left blank because the USEA directory gives two conflicting contact domains.', 'https://www.era.go.ug/certified-installation-permit-holders/', 0),
  ('cand_org_energy_systems_limited_6a4ed198', 'sweep-2026-08-epc-minigrid-025', 'agent_web_sweep', 'ENERGY SYSTEMS LIMITED', 'https://www.energysystemsug.com', 'UG', 'org_role_installer,org_role_epc', 'org_segment_commercial_industrial,org_segment_productive_use,org_segment_energy_storage', 'org_group_epcs', 'USEA member, Plot 3 Get-In House, William Street, Kampala. Own site: "planning, designing, supply, distribution, installation, maintenance and repair of various solar energy solutions", plus solar water pumping and battery storage for off-grid and on-grid applications across Uganda.', 'https://www.useaug.org/our-members/page/3/', 0),
  ('cand_org_absolute_energy_57395f85', 'sweep-2026-08-epc-minigrid-026', 'agent_web_sweep', 'Absolute Energy', '', 'UG', 'org_role_developer_ipp,org_role_om_asset_manager', 'org_segment_minigrids', 'org_group_developers', 'Named in the State of the Global Mini-Grids Market Report 2020 Uganda case study: "Italian developer Absolute Energy operates a mini-grid on Kitobo Island consisting of 230kW PV... and a 70kVA diesel generator to serve its 2,000 inhabitants"; "ERA granted Absolute Energy a framework concession for over 23 islands and a licence exemption." Corroborated by the UNREEEA article naming Absolute Energy as builder of the 230KWp Kitobo hybrid mini-grid.', 'https://minigrids.org/wp-content/uploads/2020/06/Uganda_Case_Study.pdf', 0),
  ('cand_org_kalangala_infrastructure_services_kis_3d327297', 'sweep-2026-08-epc-minigrid-026', 'agent_web_sweep', 'Kalangala Infrastructure Services (KIS)', '', 'UG', 'org_role_developer_ipp,org_role_om_asset_manager', 'org_segment_minigrids,org_segment_transmission_distribution', 'org_group_developers', 'Named in the State of the Global Mini-Grids Market Report 2020 Uganda case study: "Bugala Island has a 1.6MW solar hybrid mini-grid to serve its 30,000 inhabitants. Kalangala Infrastructure Services (KIS) operates the project under a public-private partnership with the Government of Uganda, the government-funded InfraCo Africa, and the private infrastructure developer EleQtra."', 'https://minigrids.org/wp-content/uploads/2020/06/Uganda_Case_Study.pdf', 0),
  ('cand_org_eleqtra_ac7042e6', 'sweep-2026-08-epc-minigrid-026', 'agent_web_sweep', 'EleQtra', '', 'UG', 'org_role_developer_ipp', 'org_segment_minigrids', 'org_group_developers', 'Named in the State of the Global Mini-Grids Market Report 2020 Uganda case study as "the private infrastructure developer EleQtra", a partner in the public-private partnership behind the 1.6MW Bugala Island solar hybrid mini-grid operated by Kalangala Infrastructure Services.', 'https://minigrids.org/wp-content/uploads/2020/06/Uganda_Case_Study.pdf', 0),
  ('cand_org_pamoja_energy_011ae3f1', 'sweep-2026-08-epc-minigrid-026', 'agent_web_sweep', 'Pamoja Energy', '', 'UG', 'org_role_developer_ipp,org_role_om_asset_manager', 'org_segment_minigrids', 'org_group_developers', 'Named in the State of the Global Mini-Grids Market Report 2020 Uganda case study among the independent power producers operating mini-grids in Uganda: "seven independent power producers (IPPs) operate [mini-]grids in the country, including ... Pamoja Energy."', 'https://minigrids.org/wp-content/uploads/2020/06/Uganda_Case_Study.pdf', 0),
  ('cand_org_welight_africa_b9ff4228', 'sweep-2026-08-epc-minigrid-026', 'agent_web_sweep', 'WeLight Africa', '', 'UG', 'org_role_developer_ipp,org_role_epc', 'org_segment_minigrids', 'org_group_developers', 'Named in the State of the Global Mini-Grids Market Report 2020 Uganda case study as a winning bidder in Uganda''s REA Pro Mini-Grids tender: "Winch Energy and WeLight Africa have been selected to install their projects by December 2020", serving up to 15 villages in the south and 25 in the north under a 10-year concession.', 'https://minigrids.org/wp-content/uploads/2020/06/Uganda_Case_Study.pdf', 0),
  ('cand_org_ethio_resource_group_plc_96302323', 'sweep-2026-08-epc-minigrid-026', 'agent_web_sweep', 'Ethio Resource Group PLC', '', 'ET', 'org_role_epc,org_role_om_asset_manager,org_role_developer_ipp', 'org_segment_minigrids,org_segment_productive_use', 'org_group_epcs', 'Listed in GIZ ''Table 1. List of EPC and O&M providers'' for Ethiopian cooperative mini-grids, marked Yes for demand assessment & system sizing, EPC work and O&M service; prior off-grid experience given as ''Development and operation of solar mini-grids. Experience of SHS, solar off-grid and wind solar micro-grid systems, solar water pumping''.', 'https://energypedia.info/images/7/78/Guidelines_Coop-Led_Mini-Grids_Ethiopia_GIZ_2022.pdf', 0),
  ('cand_org_alphasol_modular_energy_plc_a0392475', 'sweep-2026-08-epc-minigrid-026', 'agent_web_sweep', 'Alphasol Modular Energy PLC', '', 'ET', 'org_role_epc,org_role_om_asset_manager,org_role_installer', 'org_segment_minigrids,org_segment_shs_paygo', 'org_group_epcs', 'Listed in GIZ ''Table 1. List of EPC and O&M providers'', marked Yes for demand assessment, EPC work and O&M; prior off-grid experience ''Installation of SHS, solar institutional systems, micro-hydro, experience with biomass and wind energy''.', 'https://energypedia.info/images/7/78/Guidelines_Coop-Led_Mini-Grids_Ethiopia_GIZ_2022.pdf', 0),
  ('cand_org_gorgeous_solar_solution_e80b7100', 'sweep-2026-08-epc-minigrid-026', 'agent_web_sweep', 'Gorgeous Solar Solution', '', 'ET', 'org_role_epc,org_role_om_asset_manager,org_role_installer', 'org_segment_minigrids', 'org_group_epcs', 'Listed in GIZ ''Table 1. List of EPC and O&M providers'', marked Yes for demand assessment, EPC work and O&M; prior off-grid experience ''Installation of off-grid and grid tied solar''. Also an ESEDA member, described there as ''an off-grid solution provider for rural communities''.', 'https://energypedia.info/images/7/78/Guidelines_Coop-Led_Mini-Grids_Ethiopia_GIZ_2022.pdf', 0),
  ('cand_org_abramba_technologies_plc_8e375036', 'sweep-2026-08-epc-minigrid-026', 'agent_web_sweep', 'Abramba technologies, PLC', '', 'ET', 'org_role_distributor,org_role_installer', 'org_segment_shs_paygo', 'org_group_oems', 'Listed in GIZ ''Table 1. List of EPC and O&M providers'' (Bahir Dar, Ethiopia) but marked only ''Limited'' for demand assessment and EPC work and ''No'' for O&M; prior off-grid experience ''SHS import and distribution''. Included as a weak/limited-capability entry — treat the EPC role as unconfirmed.', 'https://energypedia.info/images/7/78/Guidelines_Coop-Led_Mini-Grids_Ethiopia_GIZ_2022.pdf', 0),
  ('cand_org_sinosoar_58745709', 'sweep-2026-08-epc-minigrid-026', 'agent_web_sweep', 'SINOSOAR', 'https://www.sinosoarhybrid.com', 'ET', 'org_role_epc,org_role_om_asset_manager,org_role_system_integrator', 'org_segment_minigrids,org_segment_energy_storage', 'org_group_epcs', 'Announced as winner of the Ethiopian Electric Utility Package II(C) Solar Mini-Grids (Generation) bid, World Bank funded, covering ''design, supply, installation, commissioning and operation and maintenance'' of solar mini-grids. A second page on the same site records SINOSOAR signing the EEU 25-Village Micro-grid Project contract (2MWp PV, 5.5MWh BESS, 450kW diesel). Chinese-headquartered (Sino Soar Hybrid (Beijing) Technology Co., Ltd.) but the contracted works are in Ethiopia.', 'https://www.sinosoarhybrid.com/eeu-world-bank-phase-iv-solar-minigrids-generation-projects-ethiopia/', 0),
  ('cand_org_acme_a01d89da', 'sweep-2026-08-epc-minigrid-026', 'agent_web_sweep', 'ACME', 'https://acme-et.com', 'ET', 'org_role_epc,org_role_installer,org_role_distributor', 'org_segment_productive_use', 'org_group_epcs', 'ESEDA member, self-described as ''an electromechanical contracting and trading company, established in 2003 G.C.'' that ''provides a wide range of engineering goods and execute turnkey projects in Energy, Water Supply, Irrigation''; services listed as ''Design, Supply, Installation & Commissioning, Training, After-sales service''.', 'https://eseda.net/our-members/', 0),
  ('cand_org_symmetry_engineering_91d41543', 'sweep-2026-08-epc-minigrid-026', 'agent_web_sweep', 'SYMMETRY ENGINEERING', '', 'ET', 'org_role_epc,org_role_installer', 'org_segment_commercial_industrial', 'org_group_epcs', 'ESEDA member, self-described as ''an MEP (mechanical, electrical, and plumbing) and solar systems contracting company established by professional mechanical and electrical engineers''.', 'https://eseda.net/our-members/', 0),
  ('cand_org_grean_world_3d175c20', 'sweep-2026-08-epc-minigrid-026', 'agent_web_sweep', 'Grean World', '', 'ET', 'org_role_epc,org_role_om_asset_manager,org_role_installer', 'org_segment_minigrids,org_segment_shs_paygo', 'org_group_epcs', 'ESEDA member; self-description claims experience in ''off-grid energy solution technical system design, capital raising, equipment procurement, construction, commissioning, and operation and maintenance of solar and backup energy systems'' for rural villages and displacement settings.', 'https://eseda.net/our-members/', 1),
  ('cand_org_green_hope_renewable_energy_works_plc_gh_721ff0ff', 'sweep-2026-08-epc-minigrid-026', 'agent_web_sweep', 'Green Hope Renewable Energy Works PLC (GHREW)', '', 'ET', 'org_role_installer,org_role_developer_ipp,org_role_om_asset_manager', 'org_segment_minigrids,org_segment_shs_paygo', 'org_group_epcs', 'ESEDA member; services self-described as ''solar PV installation, electrical maintenance, solar water pump system design, mini grid development, and electrical installation works'', plus energy development training.', 'https://eseda.net/our-members/', 0),
  ('cand_org_habeha_eco_trading_plc_b8e1aad9', 'sweep-2026-08-epc-minigrid-026', 'agent_web_sweep', 'Habeha Eco Trading plc', '', 'ET', 'org_role_installer,org_role_developer_ipp', 'org_segment_minigrids,org_segment_shs_paygo', 'org_group_epcs', 'ESEDA member; ''an Ethiopian private limited company [that] provides renewable energy solutions ... through providing social interferences by engineering solutions – solar home systems, mini-grids and solar lanterns''.', 'https://eseda.net/our-members/', 0),
  ('cand_org_mod_renewable_engineering_plc_139a4596', 'sweep-2026-08-epc-minigrid-026', 'agent_web_sweep', 'MOD Renewable Engineering PLC', 'https://modrengineering.com/', 'ET', 'org_role_installer,org_role_om_asset_manager', 'org_segment_commercial_industrial', 'org_group_epcs', 'ESEDA member; ''a renewable energy company based in Addis Ababa, Ethiopia. MOD Renewable Engineering supply, install, and maintain renewable energy solutions for homes and businesses''.', 'https://eseda.net/our-members/', 0),
  ('cand_org_global_solar_engineering_plc_a84209e6', 'sweep-2026-08-epc-minigrid-026', 'agent_web_sweep', 'Global solar engineering PLC', '', 'ET', 'org_role_installer,org_role_distributor', 'org_segment_shs_paygo,org_segment_productive_use', 'org_group_epcs', 'ESEDA member; ''a company that import, distribute and install globally certified quality solar lanterns, home systems, solar operated water pumps and other electro mechanical machines''.', 'https://eseda.net/our-members/', 0),
  ('cand_org_green_hope_trading_7b48c486', 'sweep-2026-08-epc-minigrid-026', 'agent_web_sweep', 'Green hope trading', '', 'ET', 'org_role_installer,org_role_distributor', 'org_segment_shs_paygo', 'org_group_epcs', 'ESEDA member; ''an off-grid solution providing company dedicated to enhance the access of solar energy products in Ethiopia ... through supply, installation and maintenance of quality solar energy products''.', 'https://eseda.net/our-members/', 0),
  ('cand_org_rohoboth_solar_company_29b7946f', 'sweep-2026-08-epc-minigrid-026', 'agent_web_sweep', 'Rohoboth solar company', '', 'ET', 'org_role_installer,org_role_om_asset_manager', 'org_segment_commercial_industrial', 'org_group_epcs', 'ESEDA member; ''a renewable energy solution provider for homes, organization and business center. We also supply, install and maintain uninterrupted power for urban and rural areas''.', 'https://eseda.net/our-members/', 0),
  ('cand_org_apex_energy_technologies_plc_904ae1bc', 'sweep-2026-08-epc-minigrid-026', 'agent_web_sweep', 'Apex Energy Technologies PLC', '', 'ET', 'org_role_installer', 'org_segment_shs_paygo,org_segment_commercial_industrial', 'org_group_epcs', 'ESEDA member; founded 2019, aims to ''harness this resource for off-grid communities through solar home systems and solar PV systems'' and provides backup power for urban households and businesses. Source gives only a LinkedIn page, no own domain, so website left blank.', 'https://eseda.net/our-members/', 0),
  ('cand_org_modify_electromechanical_systems_and_sol_bc25b2e3', 'sweep-2026-08-epc-minigrid-026', 'agent_web_sweep', 'MODIFY ELECTROMECHANICAL SYSTEMS AND SOLUTIONS PLC', '', 'ET', 'org_role_installer,org_role_to_classify', 'org_segment_shs_paygo,org_segment_productive_use', 'org_group_epcs', 'ESEDA member; ''a company dedicated to enhancing people lives through comprehensive solar solutions. We offer a range of products, including Solar Home Systems (SHS) and PUE to off-grid communities in Ethiopia.'' Electromechanical framing suggests installation, but the source does not state it explicitly — installer role is inferred and should be verified. Source lists only a business.site page, not an own domain.', 'https://eseda.net/our-members/', 0),
  ('cand_org_hellosolar_international_eba817e6', 'sweep-2026-08-epc-minigrid-026', 'agent_web_sweep', 'HelloSolar International', '', 'ET', 'org_role_distributor,org_role_energy_service_company', 'org_segment_shs_paygo', 'org_group_oems', 'ESEDA member; ''a decentralized off-grid solar energy solutions provider ... facilitating access to sustainable energy and connectivity through affordable PAY-as-you-go solar systems'' for rural Ethiopia. PAYGO operator rather than an EPC — no installation arm stated.', 'https://eseda.net/our-members/', 0),
  ('cand_org_benadir_energy_company_beco_391f2f90', 'sweep-2026-08-epc-minigrid-026', 'agent_web_sweep', 'Benadir Energy Company (BECO)', '', 'SO', 'org_role_developer_ipp,org_role_energy_service_company', 'org_segment_utility_generation,org_segment_transmission_distribution', 'org_group_developers', 'Named in the US Country Commercial Guide as "Somalia''s largest electric utility and the only provider in Mogadishu", operating diesel generation and having developed a 10MW solar farm outside Mogadishu. Also named as ''BECO'' in RTI''s Somalia energy sector piece and in Wikipedia''s ''Solar power in Somalia'' as builder of the country''s largest solar plant (2020). Own site beco.so was behind bot protection and could not be opened, so website left blank.', 'https://www.trade.gov/country-commercial-guides/somalia-energy-and-electricity', 0),
  ('cand_org_sompower_2dc1b175', 'sweep-2026-08-epc-minigrid-026', 'agent_web_sweep', 'SOMPOWER', '', 'SO', 'org_role_developer_ipp,org_role_energy_service_company', 'org_segment_utility_generation,org_segment_transmission_distribution', 'org_group_developers', 'Hargeisa-based private utility in Somaliland, formed in April 2016 from the merger of 39 local utility firms; ''specialises generating, transmitting and distributing of the electric power'' and operates the 20MW Hargeisa solar power station plus a 25MW diesel station. RTI separately records it investing in a hybrid solar-diesel system including a 4MW PV array.', 'https://en.wikipedia.org/wiki/Sompower', 0),
  ('cand_org_necsom_0fd352f0', 'sweep-2026-08-epc-minigrid-026', 'agent_web_sweep', 'NECSOM', '', 'SO', 'org_role_developer_ipp,org_role_energy_service_company', 'org_segment_utility_generation,org_segment_transmission_distribution', 'org_group_developers', 'Named as a Puntland-based electricity provider generating power through diesel systems and having developed wind power infrastructure (3.5MW operational since 2016). RTI''s Somalia article gives the fuller form ''National Electric Cooperation of Somalia (NECSOM)'' in Garowe and a US$6m hybrid wind/solar plus battery storage investment.', 'https://www.trade.gov/country-commercial-guides/somalia-energy-and-electricity', 0);

insert or ignore into organisation_candidates (id, batch_id, source_kind, name, website, countries, role_ids, segment_ids, actor_group_id, evidence_note, source_url, flagged_personal) values
  ('cand_org_kaah_electric_power_and_lighting_company_dd2ca664', 'sweep-2026-08-epc-minigrid-027', 'agent_web_sweep', 'KAAH Electric Power and Lighting Company Ltd (KEPLC)', '', 'SO', 'org_role_energy_service_company', 'org_segment_transmission_distribution', 'org_group_operators', 'Established 1997 as City Light Electric Company, renamed 2006; serves Hargeisa, Burao and Erigavo and ''owns and operates the entire electricity distribution system in most popular cities and towns''. Activities include network planning and maintenance. No solar generation assets described — distribution utility only.', 'https://en.wikipedia.org/wiki/KAAH_Electric', 0),
  ('cand_org_blue_sky_add5edab', 'sweep-2026-08-epc-minigrid-027', 'agent_web_sweep', 'Blue Sky', '', 'SO', 'org_role_installer,org_role_to_classify', 'org_segment_shs_paygo,org_segment_commercial_industrial', 'org_group_epcs', 'Named in the US Country Commercial Guide as a Mogadishu company that ''offers off-grid solar energy solutions''; Wikipedia''s ''Solar power in Somalia'' repeats the same trio (Blue Sky, Solargen, Delta). CAUTION: both sources give only this short trading name, no legal entity name and no website — needs manual verification before publication.', 'https://www.trade.gov/country-commercial-guides/somalia-energy-and-electricity', 1),
  ('cand_org_solargen_993df86d', 'sweep-2026-08-epc-minigrid-027', 'agent_web_sweep', 'Solargen', '', 'SO', 'org_role_installer,org_role_to_classify', 'org_segment_shs_paygo,org_segment_commercial_industrial', 'org_group_epcs', 'Named in the US Country Commercial Guide as a Mogadishu company that ''provides off-grid solar energy systems''; also listed in Wikipedia''s ''Solar power in Somalia''. CAUTION: short trading name only, no legal entity name or website given — needs manual verification.', 'https://www.trade.gov/country-commercial-guides/somalia-energy-and-electricity', 0),
  ('cand_org_red_sea_power_limited_sas_8132979f', 'sweep-2026-08-epc-minigrid-027', 'agent_web_sweep', 'Red Sea Power Limited SAS', '', 'DJ', 'org_role_developer_ipp,org_role_om_asset_manager', 'org_segment_utility_generation', 'org_group_developers', 'Named as the special purpose vehicle that constructed, operates and manages the Ghoubet wind power station in Djibouti, selling to Electricité de Djibouti. Owned by a consortium of Africa Finance Corporation, FMO''s Construction Equity Fund, Climate Fund Managers (Climate Investor One) and Great Horn Investment Holdings.', 'https://en.wikipedia.org/wiki/Ghoubet_Wind_Power_Station', 0),
  ('cand_org_grupo_auxiliar_metal_rgico_s_a_52e4bbf2', 'sweep-2026-08-epc-minigrid-027', 'agent_web_sweep', 'Grupo Auxiliar Metalúrgico S.A.', '', 'DJ', 'org_role_epc', 'org_segment_utility_generation', 'org_group_epcs', 'Named as the second member of the EPC consortium (with Siemens Gamesa Renewable Energy) for the Ghoubet wind power station in Djibouti. Spanish contractor; the works are in Djibouti.', 'https://en.wikipedia.org/wiki/Ghoubet_Wind_Power_Station', 0),
  ('cand_org_china_energy_engineering_group_shanxi_el_1c0f7357', 'sweep-2026-08-epc-minigrid-027', 'agent_web_sweep', 'China Energy Engineering Group Shanxi Electric Power Construction Co., Ltd.', '', 'ER', 'org_role_epc', 'org_segment_utility_generation,org_segment_energy_storage', 'org_group_epcs', 'Named as the firm awarded the EPC contract for Eritrea''s 30MW Dekemhare solar PV plant, announced by Eritrea''s Ministry of Energy and Mines in March 2024 and financed by the African Development Bank. Chinese contractor; the works are in Eritrea.', 'https://www.pvknowhow.com/news/30-mw-solar-pv-plant-in-eritrea-awarded-firm/', 0),
  ('cand_org_aemit_3247d88f', 'sweep-2026-08-epc-minigrid-027', 'agent_web_sweep', 'AEMIT', 'https://aemit.net', 'SD', 'org_role_epc,org_role_installer,org_role_om_asset_manager,org_role_distributor', 'org_segment_commercial_industrial,org_segment_utility_generation', 'org_group_epcs', 'Company website: full name ''African for Engineering and Management of Infrastructures and Technology (AEMIT)'', established in Khartoum, Sudan in 2018; self-described as providing ''institutional-grade EPC services'', covering engineering and design, construction and deployment, global procurement and O&M support, with LONGi and GoodWe partnerships.', 'https://aemit.net/', 0),
  ('cand_org_ses_electric_company_7b9efca2', 'sweep-2026-08-epc-minigrid-027', 'agent_web_sweep', 'SES ELECTRIC COMPANY', 'https://seselectriccompany.com', 'SD', 'org_role_epc,org_role_om_asset_manager', 'org_segment_utility_generation,org_segment_transmission_distribution', 'org_group_epcs', 'Company website: self-described as providing ''a wide range of EPC services on Industrial Projects'', with a Sudan project list including 935MW open-cycle gas plants at Garri (Khartoum) and Port Sudan as turnkey projects, maintenance on the 1250MW Merowe hydro plant, 110/220kV switchyards, and signed 50MW solar and 100MW wind development projects with STPG, Sudan.', 'https://seselectriccompany.com/our-energy-solutions/', 0),
  ('cand_org_empower_d41f84ad', 'sweep-2026-08-epc-minigrid-027', 'agent_web_sweep', 'Empower', 'https://www.empower-sudan.com', 'SD', 'org_role_epc,org_role_installer', 'org_segment_commercial_industrial,org_segment_productive_use,org_segment_utility_generation', 'org_group_epcs', 'Company website: self-described as "Sudan''s Leading Solar Energy Company" delivering grid-tie, off-grid and hybrid solar projects across industrial, agricultural, commercial and utility-scale sectors. Note: the site brands itself simply ''Empower''; a fuller legal name (''Empower Renewable Energy Co. Ltd'', Khartoum) appeared in an ENF directory listing I could not open, so it is not asserted here.', 'https://www.empower-sudan.com/', 0),
  ('cand_org_inflo_limited_c00ad1ea', 'sweep-2026-08-epc-minigrid-027', 'agent_web_sweep', 'INFLO LIMITED', '', 'MW', 'org_role_epc,org_role_installer,org_role_system_integrator', 'org_segment_minigrids,org_segment_commercial_industrial,org_segment_transmission_distribution', 'org_group_epcs', 'REIAMA member directory listing, Blantyre. Listed services: ''Solar Microgrid and Minigrid Installation - We design, supply, and install both microgrid and minigrid photovoltaic systems''; also supply, installation and maintenance of HV/MV/LV power lines and switchgear, and UPS/inverter systems. Founded 2014.', 'https://reiama.org/directory/inflo-limited/', 0),
  ('cand_org_energy_solutions_ltd_5f287229', 'sweep-2026-08-epc-minigrid-027', 'agent_web_sweep', 'Energy Solutions Ltd', '', 'MW', 'org_role_energy_service_company,org_role_equipment_supplier', 'org_segment_productive_use,org_segment_clean_cooking', 'org_group_operators', 'REIAMA member directory listing, Lilongwe, expertise tagged ''Irrigation, Solar''. Described as a Malawian green energy company established November 2015 supplying household on/off-grid lighting solutions, commercial off-grid power and lighting, agricultural water pumping systems, and manufacturing energy-efficient cookstoves. Installation is not explicitly claimed.', 'https://reiama.org/directory/energy-solutions-ltd/', 0),
  ('cand_org_sky_energy_africa_d6a0b119', 'sweep-2026-08-epc-minigrid-027', 'agent_web_sweep', 'Sky Energy Africa', '', 'MW', 'org_role_epc,org_role_installer,org_role_om_asset_manager', 'org_segment_commercial_industrial,org_segment_energy_storage,org_segment_emobility,org_segment_productive_use', 'org_group_epcs', 'REIAMA member directory listing, Blantyre. Key activities listed: ''Solar PV System Design, Supply, and Installation'' for residential, commercial, industrial, agricultural and public sector; solar water pumping; energy storage system integration; electrical engineering services and maintenance support; EV supply and EV charging infrastructure.', 'https://reiama.org/directory/sky-energy-africa/', 0),
  ('cand_org_sunray_power_company_ltd_4407b29c', 'sweep-2026-08-epc-minigrid-027', 'agent_web_sweep', 'Sunray Power Company LTD', '', 'ZM', 'org_role_epc,org_role_installer,org_role_system_integrator,org_role_om_asset_manager', 'org_segment_commercial_industrial,org_segment_minigrids,org_segment_productive_use', 'org_group_epcs', 'SIAZ member spotlight (permalink https://siaz.co.zm/member-spotlight/sunray-power-company-ltd/): ''a vertically integrated Solar Energy Company specialized in Engineering consultation and design; sourcing and procurement; distribution & supply of Solar Energy Equipment; installation; monitoring, maintenance and training'', operating since 2013. Stated expertise covers Solar Home Systems, Commercial and Industrial (C&I), Solar Mini-Grids, Solar Water Pumping and Solar Refrigeration, with ''strong te', 'https://siaz.co.zm/wp-json/wp/v2/memberspotlight?per_page=100', 0),
  ('cand_org_eccentric_engineering_limited_c5171ffd', 'sweep-2026-08-epc-minigrid-027', 'agent_web_sweep', 'ECCENTRIC ENGINEERING LIMITED', '', 'ZM', 'org_role_installer,org_role_om_asset_manager,org_role_equipment_supplier', 'org_segment_commercial_industrial', 'org_group_epcs', 'SIAZ member spotlight (permalink https://siaz.co.zm/member-spotlight/eccentric-engineering-limited/): ''Our expertise in supplying, installing, and maintaining top-notch solar equipment'', serving companies and individuals. The website address was given in the listing text.', 'https://siaz.co.zm/wp-json/wp/v2/memberspotlight?per_page=100', 0),
  ('cand_org_switch_acdc_8752285f', 'sweep-2026-08-epc-minigrid-027', 'agent_web_sweep', 'Switch ACDC', '', 'ZM', 'org_role_epc,org_role_installer,org_role_system_integrator', 'org_segment_commercial_industrial', 'org_group_epcs', 'SIAZ member spotlight (permalink https://siaz.co.zm/member-spotlight/switch-acdc/): ''offering solar energy projects of different scales... a full-service portfolio that includes consultancy, design, supply and installations'', active since early 2020, serving agricultural, commercial and residential sectors in Zambia and the wider sub-Saharan region.', 'https://siaz.co.zm/wp-json/wp/v2/memberspotlight?per_page=100', 1),
  ('cand_org_sunking_zambia_limited_867f9d26', 'sweep-2026-08-epc-minigrid-027', 'agent_web_sweep', 'SUNKING ZAMBIA LIMITED', '', 'ZM', 'org_role_energy_service_company,org_role_installer,org_role_equipment_supplier', 'org_segment_shs_paygo,org_segment_productive_use', 'org_group_operators', 'SIAZ member spotlight titled ''MEMBER SPOTLIGHT: SUNKING ZAMBIA LIMITED'' (permalink https://siaz.co.zm/member-spotlight/member-spotligt-sunking-zambia-limited/): off-grid solar company ''delivering innovative energy solutions through cutting-edge product design, affordable financing, and a grassroots installation model'', with systems powering homes, schools, hospitals, farms, offices and businesses.', 'https://siaz.co.zm/wp-json/wp/v2/memberspotlight?per_page=100', 0),
  ('cand_org_power_corner_3f90d9bd', 'sweep-2026-08-epc-minigrid-027', 'agent_web_sweep', 'Power Corner', '', 'ZM', 'org_role_developer_ipp,org_role_om_asset_manager,org_role_epc', 'org_segment_minigrids', 'org_group_developers', 'Listed in the BGFA contracted-projects table as ''Power Corner — Mini-grids — Zambia'', i.e. a BGFA-contracted mini-grid developer/operator in Zambia.', 'https://beyondthegrid.africa/our-projects/', 0),
  ('cand_org_zengamina_6dba0cce', 'sweep-2026-08-epc-minigrid-027', 'agent_web_sweep', 'Zengamina', '', 'ZM', 'org_role_developer_ipp,org_role_om_asset_manager', 'org_segment_minigrids', 'org_group_developers', 'Listed in the BGFA contracted-projects table as ''Zengamina — Mini-grids — Zambia'', i.e. a BGFA-contracted mini-grid developer/operator in Zambia.', 'https://beyondthegrid.africa/our-projects/', 0),
  ('cand_org_d_light_solar_zambia_16031fe8', 'sweep-2026-08-epc-minigrid-027', 'agent_web_sweep', 'd.light Solar Zambia', '', 'ZM', 'org_role_energy_service_company,org_role_equipment_supplier', 'org_segment_shs_paygo', 'org_group_operators', 'Listed in the BGFA contracted-projects table as ''d.light Solar Zambia — Solar home systems — Zambia''.', 'https://beyondthegrid.africa/our-projects/', 0),
