  ('cand_org_smart_roof_solar_e4600e04', 'sweep-2026-08-epc-minigrid-031', 'agent_web_sweep', 'Smart Roof Solar', '', 'BJ', 'org_role_developer_ipp,org_role_epc,org_role_installer', 'org_segment_minigrids', 'org_group_developers', 'Named among the eleven companies selected by MCA-Bénin II under the 2nd OCEF call for off-grid electrification projects (mini-grids and/or solar home system distribution).', 'https://www.24haubenin.info/?MCA-selectionne-11-entreprises-pour-executer-les-projects-OCEF', 0),
  ('cand_org_windgen_power_a391b27b', 'sweep-2026-08-epc-minigrid-031', 'agent_web_sweep', 'WIndGen Power', '', 'BJ', 'org_role_developer_ipp,org_role_epc,org_role_om_asset_manager', 'org_segment_minigrids', 'org_group_developers', 'Named among the eleven companies selected by MCA-Bénin II under the 2nd OCEF call. Capitalisation ''WIndGen Power'' is verbatim from the source and is probably a typo for ''WindGen Power''.', 'https://www.24haubenin.info/?MCA-selectionne-11-entreprises-pour-executer-les-projects-OCEF', 0),
